<?php
declare(strict_types=1);
function text_length(string $value): int { return function_exists('mb_strlen') ? mb_strlen($value, 'UTF-8') : strlen($value); }
function env_required(string $key): string { $v = getenv($key); if ($v === false || $v === '') { http_response_code(503); exit('Missing required server configuration: ' . htmlspecialchars($key, ENT_QUOTES, 'UTF-8')); } return $v; }
function app_base_url(): string { return rtrim(env_required('APP_BASE_URL'), '/'); }
function session_cookie_name(): string { return getenv('SESSION_COOKIE') ?: 'staticstack_forum_session'; }
function cookie_options(int $maxAge, bool $short = false): array { $sameSite = getenv('FRONTEND_ORIGIN') ? 'None' : 'Lax'; return ['expires'=>time()+$maxAge, 'path'=>'/', 'secure'=>true, 'httponly'=>true, 'samesite'=>$sameSite]; }
function sign_session(array $payload): string { $body = rtrim(strtr(base64_encode(json_encode($payload, JSON_UNESCAPED_SLASHES)), '+/', '-_'), '='); $sig = hash_hmac('sha256', $body, env_required('SESSION_SECRET')); return $body . '.' . $sig; }
function current_user(): ?array { $raw = $_COOKIE[session_cookie_name()] ?? ''; if (!$raw || !str_contains($raw, '.')) return null; [$body,$sig] = explode('.', $raw, 2); if (!hash_equals(hash_hmac('sha256', $body, env_required('SESSION_SECRET')), $sig)) return null; $json = base64_decode(strtr($body, '-_', '+/')); $data = $json ? json_decode($json, true) : null; if (!is_array($data) || (int)($data['exp'] ?? 0) < time() || empty($data['uid'])) return null; $adminLogin = strtolower(trim((string)getenv('ADMIN_GITHUB_LOGIN'))); $data['admin'] = $adminLogin !== '' && strtolower((string)($data['login'] ?? '')) === $adminLogin; return $data; }
function require_user(): array { $u = current_user(); if (!$u) json_response(['error'=>'Sign in with GitHub to do that.'], 401); return $u; }
function require_admin(): array { $u = require_user(); if (empty($u['admin'])) json_response(['error'=>'Administrator access is required.'], 403); return $u; }
function db(): PDO { static $pdo = null; if ($pdo instanceof PDO) return $pdo; $dsn = 'pgsql:host=' . env_required('DB_HOST') . ';port=' . env_required('DB_PORT') . ';dbname=' . env_required('DB_NAME') . ';sslmode=require'; $pdo = new PDO($dsn, env_required('DB_USERNAME'), env_required('DB_PASSWORD'), [PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION, PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC, PDO::ATTR_EMULATE_PREPARES=>false]); return $pdo; }
function json_response(array $data, int $status = 200): never { http_response_code($status); header('Content-Type: application/json; charset=utf-8'); header('Cache-Control: no-store'); echo json_encode($data, JSON_UNESCAPED_SLASHES | JSON_INVALID_UTF8_SUBSTITUTE); exit; }
function read_json(): array { $raw = file_get_contents('php://input'); $data = json_decode($raw ?: '{}', true); if (!is_array($data)) json_response(['error'=>'Invalid JSON request.'], 400); return $data; }
function require_same_origin(): void { $origin = $_SERVER['HTTP_ORIGIN'] ?? ''; if ($origin === '') return; $allowed = [app_base_url()]; $front = getenv('FRONTEND_ORIGIN'); if ($front) $allowed[] = rtrim($front, '/'); if (!in_array(rtrim($origin, '/'), $allowed, true)) json_response(['error'=>'Request origin not allowed.'], 403); }
function http_json_request(string $url, string $method, ?array $form = null, array $headers = []): array { $headers = array_merge(['User-Agent: StaticStack-Forum/1.0'], $headers); $opts = ['http'=>['method'=>$method, 'header'=>implode("\r\n", $headers), 'ignore_errors'=>true, 'timeout'=>15]]; if ($form !== null) { $opts['http']['content'] = http_build_query($form); $opts['http']['header'] .= "\r\nContent-Type: application/x-www-form-urlencoded"; } $ctx = stream_context_create($opts); $body = @file_get_contents($url, false, $ctx); if ($body === false) throw new RuntimeException('Could not contact GitHub.'); $decoded = json_decode($body, true); if (!is_array($decoded)) throw new RuntimeException('GitHub returned an invalid response.'); return $decoded; }
function ensure_schema(): void { static $done = false; if ($done) return; $pdo = db(); $pdo->exec("CREATE TABLE IF NOT EXISTS forum_users (id BIGSERIAL PRIMARY KEY, github_id BIGINT NOT NULL UNIQUE, login TEXT NOT NULL, display_name TEXT, avatar_url TEXT, is_admin BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW())"); $pdo->exec("CREATE TABLE IF NOT EXISTS forum_categories (id BIGSERIAL PRIMARY KEY, slug TEXT NOT NULL UNIQUE, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())"); $pdo->exec("CREATE TABLE IF NOT EXISTS forum_topics (id BIGSERIAL PRIMARY KEY, category_id BIGINT NOT NULL REFERENCES forum_categories(id), user_id BIGINT NOT NULL REFERENCES forum_users(id), title VARCHAR(180) NOT NULL, body TEXT NOT NULL, is_hidden BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW())"); $pdo->exec("CREATE TABLE IF NOT EXISTS forum_replies (id BIGSERIAL PRIMARY KEY, topic_id BIGINT NOT NULL REFERENCES forum_topics(id) ON DELETE CASCADE, user_id BIGINT NOT NULL REFERENCES forum_users(id), body TEXT NOT NULL, is_hidden BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW())"); $pdo->exec("CREATE TABLE IF NOT EXISTS forum_votes (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES forum_users(id) ON DELETE CASCADE, topic_id BIGINT REFERENCES forum_topics(id) ON DELETE CASCADE, reply_id BIGINT REFERENCES forum_replies(id) ON DELETE CASCADE, value SMALLINT NOT NULL CHECK(value IN (-1,1)), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), CHECK ((topic_id IS NOT NULL AND reply_id IS NULL) OR (topic_id IS NULL AND reply_id IS NOT NULL)))"); $pdo->exec("CREATE UNIQUE INDEX IF NOT EXISTS forum_votes_topic_unique ON forum_votes(user_id, topic_id) WHERE topic_id IS NOT NULL"); $pdo->exec("CREATE UNIQUE INDEX IF NOT EXISTS forum_votes_reply_unique ON forum_votes(user_id, reply_id) WHERE reply_id IS NOT NULL"); $pdo->exec("CREATE TABLE IF NOT EXISTS forum_reports (id BIGSERIAL PRIMARY KEY, reporter_id BIGINT NOT NULL REFERENCES forum_users(id), topic_id BIGINT REFERENCES forum_topics(id) ON DELETE CASCADE, reply_id BIGINT REFERENCES forum_replies(id) ON DELETE CASCADE, reason VARCHAR(500) NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','resolved','dismissed')), reviewed_by BIGINT REFERENCES forum_users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), reviewed_at TIMESTAMPTZ, CHECK ((topic_id IS NOT NULL AND reply_id IS NULL) OR (topic_id IS NULL AND reply_id IS NOT NULL)))"); $pdo->exec("CREATE INDEX IF NOT EXISTS forum_topics_category_created_idx ON forum_topics(category_id, created_at DESC)"); $pdo->exec("CREATE INDEX IF NOT EXISTS forum_replies_topic_created_idx ON forum_replies(topic_id, created_at ASC)"); $pdo->exec("CREATE INDEX IF NOT EXISTS forum_reports_status_created_idx ON forum_reports(status, created_at DESC)"); $seed = $pdo->prepare('INSERT INTO forum_categories (slug,name,description) VALUES (:slug,:name,:description) ON CONFLICT (slug) DO NOTHING'); foreach ([['help','Help and Questions','Ask questions about building and maintaining static websites.'],['tools','Tools and Components','Share useful tools, scripts, libraries, and components.'],['showcase','Show and Tell','Show the static websites and projects you are building.'],['discussion','General Discussion','Talk about HTML, CSS, JavaScript, and the static web.']] as $c) $seed->execute([':slug'=>$c[0],':name'=>$c[1],':description'=>$c[2]]); $done = true; }
